-- Generated by scripts/generar-seed-entrevista.py from Check List Entrevista Práctica.
values ('ENTREVISTA_PRACTICA','Evaluación práctica de cocina',1,true)
on conflict (codigo) do update set nombre=excluded.nombre, version=excluded.version, activa=excluded.activa;
create temporary table import_sections(codigo text,titulo text,instruccion text,orden int) on commit drop;
select p.id,i.codigo,i.titulo,i.instruccion,i.orden from import_sections i
join public.entrevista_plantillas p on p.codigo='ENTREVISTA_PRACTICA'
on conflict (plantilla_id,codigo) do update set titulo=excluded.titulo,
  instruccion=excluded.instruccion, orden=excluded.orden;
create temporary table import_criteria(seccion text,titulo text,instruccion text,orden int,texto text) on commit drop;
select p.id,s.id,'ENC_' || right('00' || c.orden::text,3),c.texto,c.orden
from import_criteria c
join public.entrevista_plantillas p on p.codigo='ENTREVISTA_PRACTICA'
join public.entrevista_secciones s on s.plantilla_id=p.id and s.titulo=c.titulo
on conflict (codigo) do update set seccion_id=excluded.seccion_id, texto=excluded.texto, orden=excluded.orden;
drop table pg_temp.import_sections;
drop table pg_temp.import_criteria;
do $$ begin
  if (select count(*) from public.entrevista_secciones) <> 6 or
     (select count(*) from public.entrevista_criterios) <> 40 then
    raise exception 'Interview template must contain 6 sections and 40 criteria';
  end if;
end $$;
